<script setup>
import { ref } from 'vue';
import { Link, router } from '@inertiajs/vue3';
import AssessmentLayout from './AssessmentLayout.vue';
const props=defineProps({creations:Object,filters:Object,isAdmin:Boolean});
const search=ref(props.filters?.search || ''); const reviewStatus=ref(props.filters?.review_status || 'pending'); const scope=ref(props.filters?.scope || 'all');
const apply=()=>router.get(route('redesign.creations.queue'),{search:search.value || undefined,review_status:reviewStatus.value,scope:scope.value},{preserveState:true,replace:true});
</script>
<template><AssessmentLayout title="Creation review queue" subtitle="Tinjau karya dan kelola penugasan reviewer." breadcrumb="Komunitas & pengguna"><div class="tabs"><Link :class="{active:filters?.review_status==='all'}" :href="route('redesign.creations.queue',{review_status:'all'})">Semua</Link><Link :class="{active:filters?.scope==='assigned'}" :href="route('redesign.creations.queue',{review_status:'all',scope:'assigned'})">Ditugaskan ke saya</Link><Link :class="{active:filters?.review_status==='approved'}" :href="route('redesign.creations.queue',{review_status:'approved'})">Selesai</Link></div><form class="filters" @submit.prevent="apply"><input v-model="search" aria-label="Cari karya" placeholder="Cari judul, kreator, atau kategori..." /><select v-model="reviewStatus" aria-label="Status review"><option value="all">Semua status</option><option value="pending">Menunggu</option><option value="needs_revision">Perlu revisi</option><option value="approved">Disetujui</option><option value="none">Belum diajukan</option></select><button class="action">Filter</button><Link class="secondary" :href="route('redesign.creations.queue',{review_status:'all'})">Reset</Link></form><section class="panel"><h2>Creation review queue</h2><div class="table-wrap"><table><thead><tr><th>Karya / kreator</th><th>Status review</th><th>Reviewer</th><th>Rubrik</th><th>Hasil</th></tr></thead><tbody><tr v-for="item in creations?.data || []" :key="item.id"><td><Link class="row-link" :href="route('redesign.creations.review',item.slug)">{{ item.title }} / {{ item.creator?.name || item.creator?.username }}</Link></td><td>{{ item.review_status }}</td><td>{{ item.assigned_reviewer?.name || 'Belum ditugaskan' }}</td><td>{{ item.assigned_rubric?.title || 'Belum dipilih' }}</td><td>{{ item.final_review?.score_percent ?? '—' }}</td></tr><tr v-if="!creations?.data?.length"><td colspan="5" class="muted">Tidak ada karya yang cocok.</td></tr></tbody></table></div><div class="pager"><Link v-for="(link,i) in creations?.links || []" :key="i" :href="link.url || '#'" :class="{active:link.active,disabled:!link.url}" v-html="link.label" /></div></section></AssessmentLayout></template>
<style scoped>.row-link{color:#19333d;font-weight:700;text-decoration:underline;text-decoration-color:#9ccbc6;text-underline-offset:3px}</style>
